#!/usr/bin/env python3
"""Validate claims.csv against the tracker schema.

Usage: python validate.py [path/to/claims.csv]
Exit code 0 if valid, 1 otherwise. Prints one line per problem.
"""
import csv
import re
import sys
from pathlib import Path

COLUMNS = [
    "id", "claim", "source_title", "source_url", "source_org", "date_published",
    "models_tested", "category", "code_released", "data_released",
    "models_still_available", "est_cost_usd", "decision_relevance", "status",
    "replication_url", "replicated_by", "notes", "added_by", "date_added",
]

ENUMS = {
    "category": {
        "sandbagging", "sycophancy", "deception", "cot-faithfulness",
        "reward-hacking", "jailbreak-robustness", "fine-tuning-safety",
        "situational-awareness", "agentic-misbehaviour", "other",
    },
    "code_released": {"yes", "partial", "no"},
    "data_released": {"yes", "partial", "no"},
    "models_still_available": {"yes", "some", "no", "unknown"},
    "est_cost_usd": {"<100", "100-1000", "1000-5000", ">5000", "unknown"},
    "decision_relevance": {"1", "2", "3"},
    "status": {
        "not-attempted", "in-progress", "reproduced", "partially-reproduced",
        "not-reproduced", "not-reproducible-from-released-materials",
    },
}

REQUIRED = ["id", "claim", "source_title", "source_url", "source_org",
            "date_published", "category", "status", "added_by", "date_added"]

ID_RE = re.compile(r"^HT-\d{4}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
URL_RE = re.compile(r"^https?://")


def validate(path: Path) -> list[str]:
    problems: list[str] = []
    with path.open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != COLUMNS:
            problems.append(f"header mismatch: expected {COLUMNS}, got {reader.fieldnames}")
            return problems
        seen_ids: set[str] = set()
        for n, row in enumerate(reader, start=2):
            where = f"line {n} ({row.get('id') or 'no id'})"
            for col in REQUIRED:
                if not row.get(col, "").strip():
                    problems.append(f"{where}: missing required field '{col}'")
            rid = row.get("id", "")
            if rid and not ID_RE.match(rid):
                problems.append(f"{where}: id must look like HT-0001")
            if rid in seen_ids:
                problems.append(f"{where}: duplicate id")
            seen_ids.add(rid)
            for col in ("date_published", "date_added"):
                v = row.get(col, "").strip()
                if v and not DATE_RE.match(v):
                    problems.append(f"{where}: {col} must be YYYY-MM-DD")
            for col in ("source_url", "replication_url"):
                v = row.get(col, "").strip()
                if v and not URL_RE.match(v):
                    problems.append(f"{where}: {col} must start with http(s)://")
            for col, allowed in ENUMS.items():
                v = row.get(col, "").strip()
                if v and v not in allowed:
                    problems.append(f"{where}: {col}='{v}' not in {sorted(allowed)}")
            if row.get("status") in {"reproduced", "partially-reproduced", "not-reproduced"}:
                if not row.get("replication_url", "").strip():
                    problems.append(f"{where}: status '{row['status']}' needs a replication_url")
            if len(row.get("claim", "")) > 300:
                problems.append(f"{where}: claim is over 300 chars; make it one sentence")
    return problems


def main() -> int:
    path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parent.parent / "claims.csv"
    if not path.exists():
        print(f"no such file: {path}")
        return 1
    problems = validate(path)
    for p in problems:
        print(p)
    print(f"{'OK' if not problems else 'FAILED'}: {path} ({len(problems)} problem(s))")
    return 0 if not problems else 1


if __name__ == "__main__":
    sys.exit(main())
